const body = $input.first().json.body;
const dest = body.destination || '台灣';
const dailyAreas = (body.daily_area || []).filter(a => a && a !== '不限區域');
const areasStr = dailyAreas.length > 0 ? dailyAreas.join(' ') : dest;
const preference = body.preference || '一般旅遊';
const spotQuery = `${dest} ${areasStr} 旅遊景點推薦 必去景點 ${preference} 評價`;
const foodQuery = `${dest} ${areasStr} 必吃美食推薦 在地美食 餐廳 小吃 2024`;
const activityQuery = `${dest} ${areasStr} 一日遊 體驗活動 旅遊行程 KKday Klook 推薦`;
return [{ json: { body, spot_query: spotQuery, food_query: foodQuery, activity_query: activityQuery } }];

const spotResults = $input.first().json;
const prepareData = $('Prepare').first().json;
const spotSnippets = (spotResults.organic || []).slice(0, 6).map((r, i) => `[${i+1}] ${r.title}\n${r.snippet || ''}`).join('\n');
return [{ json: { body: prepareData.body, food_query: prepareData.food_query, activity_query: prepareData.activity_query, spot_summary: spotSnippets } }];

const captured = $('Capture Spots').first().json;
const foodResults = $input.first().json;
const foodSnippets = (foodResults.organic || []).slice(0, 8).map((r, i) => `[${i+1}] ${r.title}: ${r.snippet || ''}`).join('\n').substring(0, 2000);
return [{ json: { body: captured.body, activity_query: captured.activity_query, spot_summary: captured.spot_summary, food_summary: foodSnippets } }];

const capturedFood = $('Capture Food').first().json;
const body = capturedFood.body;
const actResults = $input.first().json;

const actSnippets = (actResults.organic || []).slice(0, 5).map((r, i) => `[${i+1}] ${r.title}: ${r.snippet || ''} ${r.link || ''}`).join('\n').substring(0, 1500);

const dailyAreaArr = body.daily_area || [];
const dailyDirArr = body.daily_direction || [];
const dailyAreaStr = JSON.stringify(dailyAreaArr);
const dailyDirStr = dailyDirArr.map((d, i) => d ? `第 ${i+1} 天：${d}` : '').filter(Boolean).join('\n') || '無';

const areaRules = dailyAreaArr.map((area, i) =>
  area && area !== '不限區域'
    ? `第 ${i+1} 天：所有景點【必須】在「${area}」範圍內，嚴禁安排其他區域景點`
    : `第 ${i+1} 天：自由安排`
).join('\n');

const departHour = parseInt((body.depart_time || '09:00').split(':')[0]);
const returnHour = parseInt((body.return_time || '15:00').split(':')[0]);

let timeRules = '';
if (departHour >= 11) timeRules += '- 第一天從下午開始排，不排早上景點\n';
else if (departHour >= 10) timeRules += '- 第一天早上只排1個景點\n';
if (returnHour <= 11) timeRules += '- 最後一天不排任何景點\n';
else if (returnHour <= 14) timeRules += '- 最後一天只排早上，不排下午\n';
timeRules += `- 最後一天 ${body.return_time || '15:00'} 前2小時停止安排景點`;

const specialNote = body.special_request ? `特別需求（優先排入）：${body.special_request}` : '';

const systemPrompt = `你是台灣旅遊規劃專家。根據以下最新網路搜尋結果和使用者條件，規劃詳細的旅遊行程。請優先使用搜尋結果中出現的景點和餐廳。

=== 最新景點搜尋結果 ===
${capturedFood.spot_summary}

=== 最新美食搜尋結果 ===
${capturedFood.food_summary}

=== KKday/Klook 體驗活動搜尋結果 ===
${actSnippets}

==== 每天區域限制（最高優先級，違反視為錯誤） ====
${areaRules}
例如：七星潭屬於吉安鄉，若第1天指定花蓮市區，七星潭絕對不可出現在第1天。

重要規則：
1. 只回傳純 JSON，不可加任何說明文字或 markdown
2. 每天：早上2個、下午2個、晚上1個（時間規則例外）
3. type 只能填「景點」或「美食"
4. note 是一句30字以內的中文介紹（根據搜尋結果整理）
5. 每個景點必須提供 nearby_food（3-5 個真實店家）
6. nearby_food 必須有具體店名，不接受籠統描述
7. 夜市類景點的 nearby_food 改為夜市內 3-5 個具體必吃攤位
8. 座標 lat/lng 必須準確（緯度 21-26.5，經度 118-123）
9. maps_url 格式：https://maps.google.com/?q=景點名稱+城市
10. 若 KKday/Klook 搜尋結果有相關體驗，加入 activities 陣列（最多2個）：[{"title":"xxx","platform":"KKday","url":"xxx","price_from":"NT$XXX 起"}]；沒有則填空陣列

時間邏輯（嚴格遵守）：
早上只能排：自然景觀、博物館、老街、早市、咖啡廳（禁止夜市、夜景）
下午只能排：景點參觀、下午茶、海灘、文創園區（禁止夜市、夜景）
晚上只能排：夜市、夜景、燈會、晚餐名店（禁止一般白天景點）
${timeRules}

${specialNote}

輸出格式（必須包含所有 ${body.days} 天，不可省略）：
{"title":"城市名","days":天數,"itinerary":[{"day":1,"area":"區域名","morning":[{"type":"景點","name":"名稱","note":"介紹","address":"地址","maps_url":"url","lat":00.0000,"lng":000.0000,"nearby_food":[{"name":"店名","type":"類型","note":"介紹","address":"地址"}],"activities":[],"photo_keyword":"English keyword for Unsplash photo (e.g. Taroko Gorge Taiwan)"}],"afternoon":[...],"evening":[...]}]}`;

const userMessage = `請為以下條件規劃行程：\n目的地：${body.destination}，天數：${body.days}天\n大人：${body.adults}人，小孩：${body.kids || 0}人\n旅遊傾向：${body.preference}，住宿：${body.accommodation}\n每天區域：${dailyAreaStr}\n每天方向：${dailyDirStr}\n\n重要提醒：必須輸出完整的 ${body.days} 天行程，不可只輸出1天。`;

const maxTokens = Math.min(body.days * 2000 + 2000, 12000);

return [{ json: { model: 'gpt-4o-mini', response_format: { type: 'json_object' }, temperature: 0.8, max_tokens: maxTokens, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }] } }];

const raw = $input.first().json.choices[0].message.content;
const result = JSON.parse(raw);
return [{ json: result }];
